pub(super) fn for_path(path: &str) -> &'static Icon {
    let base = path
        .rsplit('/')
        .find(|part| !part.is_empty())
        .unwrap_or(path);
    let base = base.rsplit_once(':').map_or(base, |(name, suffix)| {
        let mut parts = suffix.split('-');
        let line = parts
            .next()
            .is_some_and(|part| !part.is_empty() && part.bytes().all(|b| b.is_ascii_digit()));
        let end = parts.next();
        if line
            && end.is_none_or(|part| !part.is_empty() && part.bytes().all(|b| b.is_ascii_digit()))
            && parts.next().is_none()
        {
            name
        } else {
            base
        }
    });
    let lower = base.to_ascii_lowercase();
    match lower.as_str() {
        "dockerfile" | ".dockerignore" => return &DOCKER,
        "gemfile" | "gemfile.lock" => return &BUNDLER,
        "cargo.toml" | "cargo.lock" => return &CARGO,
        "bun.lock" | "bun.lockb" => return &BUN,
        "poetry.lock" => return &POETRY,
        "requirements.txt" => return &PIP,
        "turbo.json" => return &TURBO,
        "svelte.config.js" => return &SVELTE,
        "license" => return &LICENSE,
        _ if lower.starts_with(".env") => return &DOTENV,
        _ if lower.starts_with("nuxt.config.") => return &NUXT,
        _ => {}
    }
    let ext = lower.rsplit('.').next().unwrap_or("");
    match ext {
        "go" => &GO,
        "sh" | "bash" | "zsh" => &SHELL,
        "yaml" | "yml" => &YAML,
        "toml" => &TOML,
        "sql" => &SQL,
        "java" => &JAVA,
        "c" => &C,
        "h" => &C_HEADER,
        "cpp" | "cc" | "cxx" => &CPP,
        "hpp" => &CPP_HEADER,
        "swift" => &SWIFT,
        "rb" => &RUBY,
        "xml" => &XML,
        "pdf" => &PDF,
        "png" | "jpg" | "jpeg" | "gif" => &IMAGE,
        "svg" => &SVG,
        "webp" => &WEBP,
        "graphql" | "gql" => &GRAPHQL,
        "proto" => &PROTOBUF,
        "vue" => &VUE,
        "ts" => &TS,
        "tsx" => &REACT_TS,
        "js" | "mjs" | "cjs" => &JS,
        "jsx" => &REACT_JS,
        "rs" => &RUST,
        "json" => &JSON,
        "md" => &MD,
        "mdx" => &MDX,
        "html" => &HTML,
        "css" => &CSS,
        "py" => &PY,
        "svelte" => &SVELTE,
        _ => &DEFAULT,
    }
}

#[cfg(test)]
mod tests {
    use super::for_path;

    #[test]
    fn file_icons_resolve_overrides_and_line_suffixes() {
        for (path, expected) in [
            ("src/Cargo.toml:12-14", "file-type-cargo"),
            (".env.production", "file-type-dotenv"),
            ("src/main.go:22", "file-type-go"),
            ("include/test.hpp", "file-type-cppheader"),
            ("logo.svg", "file-type-svg"),
            ("thing.unknown", "default-file"),
        ] {
            assert_eq!(for_path(path).name, expected, "{path}");
        }
    }
}
